const filename = $('Prepare compilation ready').first().json.filename || "Resume.pdf";
const candidateName = $('Prepare compilation ready').first().json.candidateName || "Candidate";
const item = $input.first();
return [{
  json: { filename, candidateName },
  binary: { pdfData: item.binary.pdfData }
}];

const raw = $input.first().json.output || "";
let candidateName = "Candidate";
try {
  const resumeOutput = $('Resume extractor').first().json.output || "";
  const nameMatch = resumeOutput.match(/"full_name"\s*:\s*"([^"]+)"/);
  if (nameMatch) candidateName = nameMatch[1];
} catch(e) {}
const safeFilename = candidateName.replace(/[^a-zA-Z0-9\s]/g, "").trim().replace(/\s+/g, "_") + "_Resume.pdf";
let latex = raw
  .replace(/^```latex\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```\s*$/i, "")
  .trim();
const docStart = latex.indexOf("\\documentclass");
if (docStart > 0) latex = latex.slice(docStart);
const docEnd = latex.lastIndexOf("\\end{document}");
if (docEnd !== -1) latex = latex.slice(0, docEnd + "\\end{document}".length);
const requestBody = JSON.stringify({
  compiler: "pdflatex",
  resources: [{ main: true, content: latex }]
});
return [{ 
  json: { 
    requestBody, filename: safeFilename, candidateName,
    latexPreview: latex.slice(0, 200)
  } 
}];

let atsScore = 0; let atsRecommendation = "N/A"; let atsGaps = []; let atsKeywords = [];
try {
  const atsRaw = $('ATS Score Agent').first().json.output || "";
  const atsClean = atsRaw.replace(/```json/gi, "").replace(/```/g, "").trim();
  const firstBrace = atsClean.indexOf("{");
  const lastBrace = atsClean.lastIndexOf("}");
  const atsJson = JSON.parse(atsClean.slice(firstBrace, lastBrace + 1));
  atsScore = atsJson.score || 0;
  atsRecommendation = atsJson.recommendation || "N/A";
  atsGaps = atsJson.gaps || [];
  atsKeywords = atsJson.top_matching_keywords || [];
} catch(e) { atsGaps = ["Could not parse ATS analysis"]; }

function scoreBar(score) {
  const filled = Math.round(score / 10);
  return "🟩".repeat(filled) + "⬜".repeat(10 - filled);
}
function recommendationEmoji(rec) {
  if (rec.includes("Strong")) return "🚀";
  if (rec.includes("Good")) return "✅";
  if (rec.includes("Moderate")) return "⚠️";
  return "🔴";
}

const candidateName = $('Compile & convert to pdf file').first().json.candidateName || "Candidate";
const filename = $('Compile & convert to pdf file').first().json.filename || "Resume.pdf";
const gapLines = atsGaps.map((g, i) => `   ${i + 1}. ${g}`).join("\n");
const caption = `${recommendationEmoji(atsRecommendation)} *${candidateName}* — Resume Ready\n\n📊 *ATS Match Score: ${atsScore}/100*\n${scoreBar(atsScore)} ${atsRecommendation}\n\n🔍 *Top Gaps:*\n${gapLines}\n\n📄 ${filename}\n🤖 ATS-optimized & JD-matched`;

let coverLetterHtml = "";
try {
  let clRaw = $('Cover Letter Agent').first().json.output || "";
  clRaw = clRaw.replace(/```html/gi, "").replace(/```/g, "").trim();
  if (clRaw.startsWith("<") && clRaw.includes("</html>")) {
    const htmlStart = clRaw.indexOf("<");
    const htmlEnd = clRaw.lastIndexOf("</html>") + 7;
    coverLetterHtml = clRaw.slice(htmlStart, htmlEnd);
  }
} catch(e) {}

const safeName = candidateName.replace(/[^a-zA-Z0-9\s]/g, "").trim().replace(/\s+/g, "_");

const items = [{ json: { caption, filename, candidateName } }];

if (coverLetterHtml) {
  items[0].binary = {
    coverLetterFile: {
      data: Buffer.from(coverLetterHtml, "utf-8").toString("base64"),
      mimeType: "text/html",
      fileName: `${safeName}_Cover_Letter.html`
    }
  };
}

return items;

const resumeOutput = $('Resume extractor').first().json.output || "{}";
const jdOutput = $('JD extractor').first().json.output || "{}";
let resumeJson, jdJson;
try { resumeJson = JSON.parse(resumeOutput); } catch(e) { resumeJson = {}; }
try { jdJson = JSON.parse(jdOutput); } catch(e) { jdJson = {}; }

const name = resumeJson?.candidate_identity?.full_name || "Professional";
const role = jdJson?.role_title || "Target Role";
const skills = resumeJson?.skill_matrix?.technical_skills || {};
const skillList = Object.values(skills).flat().slice(0, 10).join(", ");

const imagePrompt = `Professional LinkedIn banner for ${name}, a ${role} specialist. Skills: ${skillList}. Style: clean, modern, tech-themed with blue gradient, abstract circuit board patterns, minimalist design. Text overlay: "${name} | ${role}". 1200x600 pixels.`;

const videoPrompt = `Professional portfolio showcase video for ${name}, a skilled ${role} professional. ${skillList}. 15 seconds, cinematic transitions, modern corporate style, blue and white color scheme, animated text showing key achievements and skills.`;

return [{
  json: {
    imagePrompt,
    videoPrompt,
    candidateName: name,
    role: role
  }
}];

const response = $input.first().json;
let imageUrl = "";
if (response.data && response.data[0] && response.data[0].url) {
  imageUrl = response.data[0].url;
}
const caption = `🖼️ *Portfolio Banner Generated*\n\nGenerated for: ${$('Build Media Prompts').item.json.candidateName}\nRole: ${$('Build Media Prompts').item.json.role}`;
return [{
  json: { imageUrl, caption, ...$input.first().json }
}];

const results = $input.all();
let bestVideo = null;
let bestImage = null;
let captions = [];

for (const item of results) {
  if (item.json.imageUrl) bestImage = item.json.imageUrl;
  if (item.json.videoUrl || item.json.id) {
    if (!bestVideo || (item.json.model && item.json.model.includes("pro"))) {
      bestVideo = item.json;
    }
  }
  if (item.json.caption) captions.push(item.json.caption);
}

return [{
  json: {
    bestImageUrl: bestImage,
    bestVideoUrl: bestVideo?.videoUrl || bestVideo?.url,
    candidateName: $('Build Media Prompts').item.json.candidateName,
    caption: `🎬 *Portfolio Media Ready!*\n\n👤 ${$('Build Media Prompts').item.json.candidateName}\n🖼️ Banner: ${bestImage ? '✅ Generated' : '❌ Failed'}\n🎬 Video: ${bestVideo ? '✅ Generated' : '❌ Failed'}`
  }
}];

const mediaChoice = $('Resume & JD submitted').item.json['Generate Portfolio Media? 🎨'];
const mediaNodes = ['Build Media Prompts', 'Generate Image (OpenAI DALL-E 3)', 'Generate Video (OpenAI Sora 2 Pro)', 'Generate Video (Google Veo 3.1)', 'Generate Video (xAI Grok Imagine)', 'Generate Video (ByteDance Seedance 2.0)', 'Merge Media Results', 'Finalize Media Output', 'Send Video via Telegram'];
if (mediaChoice === 'none') {
  return [{ json: { skipMedia: true } }];
}
return [{ json: { skipMedia: false, mediaChoice } }];
